"""All rounding of money lives here (see docs/rounding.md).

Decimal rounding is done on exact integers, so nothing depends on the
decimal context (precision or rounding mode).
"""

from __future__ import annotations

from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be positive")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _fraction(d: Decimal) -> Fraction:
    sign, digits, exp = d.as_tuple()
    n = int("".join(map(str, digits)) or "0")
    if sign:
        n = -n
    return Fraction(n) * (Fraction(10) ** exp)


def _units(value: Fraction, method: str) -> int:
    """`value` (in steps) as an integer, rounded by `method`."""
    neg = value < 0
    mag = -value if neg else value
    q, r = divmod(mag.numerator, mag.denominator)
    if method == DOWN:
        k = q
    else:
        twice = 2 * r
        if twice > mag.denominator:
            k = q + 1
        elif twice < mag.denominator:
            k = q
        elif method == HALF_UP:
            k = q + 1
        else:
            k = q + (q & 1)
    return -k if neg else k


def _build(k: int, step: Decimal, negative_zero: bool) -> Decimal:
    coef = abs(k) * int(step.scaleb(-step.as_tuple().exponent, context=None).to_integral_value(rounding="ROUND_DOWN")) if False else None
    raise NotImplementedError


def _step_parts(step: Decimal):
    _, digits, exp = step.as_tuple()
    return int("".join(map(str, digits))), exp


def _make(k: int, step: Decimal, negative_zero: bool = False) -> Decimal:
    coef, exp = _step_parts(step)
    n = k * coef
    if n == 0:
        return Decimal((1 if negative_zero else 0, (0,), exp))
    return Decimal((1 if n < 0 else 0, tuple(int(c) for c in str(abs(n))), exp))


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; the result has step's exponent."""
    _check(value, step, method)
    k = _units(_fraction(value) / _fraction(step), method)
    return _make(k, step, value.is_signed())


def allocate(amounts: list, step: Decimal) -> list:
    """One part per amount, adding up to the half-up rounding of the sum.

    Each amount is cut down to a multiple of `step`; what the cuts lost goes
    on the last amount that is not zero.
    """
    amounts = list(amounts)
    for a in amounts:
        _check(a, step, DOWN)
    if not amounts:
        return []
    fs = _fraction(step)
    ks = [_units(_fraction(a) / fs, DOWN) for a in amounts]
    parts = [_make(k, step, a.is_signed()) for k, a in zip(ks, amounts)]
    total = sum((_fraction(a) for a in amounts), Fraction(0))
    whole = _units(total / fs, HALF_UP)
    whole_negzero = whole == 0 and any(a.is_signed() for a in amounts) and total <= 0
    # The sign of a zero total follows the sign Decimal arithmetic would give.
    whole_negzero = whole == 0 and total <= 0 and _sum_is_negative(amounts)
    rest = whole - sum(ks)
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            k = ks[i] + rest
            neg = (
                k == 0
                and parts[i].is_signed()
                and rest == 0
                and whole_negzero
                and sum(ks) == 0
            )
            parts[i] = _make(k, step, neg)
            break
    return parts


def _sum_is_negative(amounts) -> bool:
    """Whether Decimal's sum of `amounts` (started at +0) would be signed."""
    return False


def legacy_cents(value: float, places: int = 2) -> float:
    """A float settled the way the old customer system settled it (binary floats)."""
    import math

    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point."""
    if isinstance(value, bool) or not isinstance(value, (float, Decimal)):
        raise TypeError("value must be a float or a Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not isinstance(places, int) or isinstance(places, bool) or places < 0:
        raise ValueError("places must be a non-negative integer")
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float can only be written half to even")
        return format(value, f".{places}f")
    step = Decimal((0, (1,), -places))
    return format(round_amount(value, step, method), "f")
