import json, random, subprocess, os, sys, shutil
random.seed(5)
def dec(n,f): return f"{random.randint(0,10**n):d}".rjust(f+1,'0')[:-f]+"."+f"{random.randint(0,10**f-1):0{f}d}" if f else str(random.randint(0,10**n))
shutil.rmtree('/tmp/fz',ignore_errors=True); os.makedirs('/tmp/fz/acc')
cashes=["none","whole","0.05","0.10","0.5","5","0.25"]
def book(i):
    cur={c:{"cash":random.choice(cashes)} for c in "ABC"}
    t={}
    for n in range(3):
        k=sorted(random.sample(range(1,300),2)); 
        t[f"t{n}"]={"currency":random.choice("ABC"),"vat":random.choice(["0.21","0.055","0.125","0.2","0.0725","0"]),
