    p=f"/tmp/fz/book{i}.json"; json.dump({"currencies":cur,"tariffs":t},open(p,'w')); return p
books=[book(i) for i in range(6)]
for i in range(60):
    s=random.randint(1,20)
    acc={"account":f"A{i}","name":"n","tariff":f"t{random.randint(0,2)}","period":{"start":"2026-03-01","end":f"2026-03-{random.randint(1,30):02d}"},
     "readings":[{"meter":"M","kwh":random.choice([dec(3,1),dec(3,2),dec(3,3),str(random.randint(0,400)),"0"])} for _ in range(random.randint(0,3))],
     "credits":[{"ref":"c","amount":random.choice([-4.25,0.005,1.005,2.675,-0.004,0.015,-0.005,3,1e-9,-1.255,123456.785])} for _ in range(random.randint(0,3))]}
    if random.random()<.5:
        acc["standing"]=[{"from":"2026-03-01","to":acc["period"]["end"],"rate":random.choice(["0.4110","0.125","-0.001","0","0.0049","0.0051"])}]
    json.dump(acc,open(f"/tmp/fz/acc/a{i}.json","w"))
def run(pkg,args):
    r=subprocess.run([sys.executable,"-m","meterbill"]+args,cwd=pkg,capture_output=True,text=True); return (r.stdout,r.stderr,r.returncode)
bad=0;n=0
for b in books:
    cmds=[["tariffs"],["batch","/tmp/fz/acc"],["batch","/tmp/fz/acc","--format","csv"],["batch","/tmp/fz/acc","--workers","1"]]
    for t in range(3):
        for _ in range(6): cmds.append(["quote",f"t{t}",random.choice([dec(3,1),dec(3,2),dec(3,3),"0"]),str(random.randint(1,40))])
        cmds.append(["quote",f"t{t}","12.5","3","--format","json"])
    for i in range(0,60,3):
        for f in("text","csv","json"): cmds.append(["bill",f"/tmp/fz/acc/a{i}.json","--format",f])
    for c in cmds:
        a=["--tariffs",b]+c
        n+=1
        if run("/tmp/orig",a)!=run("/app",a):
            bad+=1; print("DIFF",a) if bad<5 else 0
print(n,bad)
